29: sz_psz2ind(size_t psz) {
30: 	assert(psz > 0);
31: 	if (unlikely(psz > SC_LARGE_MAXCLASS)) {
32: 		return SC_NPSIZES;
33: 	}
34: 	/* x is the lg of the first base >= psz. */
35: 	pszind_t x = lg_ceil(psz);
36: 	/*
37: 	 * sc.h introduces a lot of size classes. These size classes are divided
38: 	 * into different size class groups. There is a very special size class
39: 	 * group, each size class in or after it is an integer multiple of PAGE.
40: 	 * We call it first_ps_rg. It means first page size regular group. The
41: 	 * range of first_ps_rg is (base, base * 2], and base == PAGE *
42: 	 * SC_NGROUP. off_to_first_ps_rg begins from 1, instead of 0. e.g.
43: 	 * off_to_first_ps_rg is 1 when psz is (PAGE * SC_NGROUP + 1).
44: 	 */
45: 	pszind_t off_to_first_ps_rg = (x < SC_LG_NGROUP + LG_PAGE) ?
46: 	    0 : x - (SC_LG_NGROUP + LG_PAGE);
47: 
48: 	/*
49: 	 * Same as sc_s::lg_delta.
50: 	 * Delta for off_to_first_ps_rg == 1 is PAGE,
51: 	 * for each increase in offset, it's multiplied by two.
52: 	 * Therefore, lg_delta = LG_PAGE + (off_to_first_ps_rg - 1).
53: 	 */
54: 	pszind_t lg_delta = (off_to_first_ps_rg == 0) ?
55: 	    LG_PAGE : LG_PAGE + (off_to_first_ps_rg - 1);
56: 
57: 	/*
58: 	 * Let's write psz in binary, e.g. 0011 for 0x3, 0111 for 0x7.
59: 	 * The leftmost bits whose len is lg_base decide the base of psz.
60: 	 * The rightmost bits whose len is lg_delta decide (pgz % PAGE).
61: 	 * The middle bits whose len is SC_LG_NGROUP decide ndelta.
62: 	 * ndelta is offset to the first size class in the size class group,
63: 	 * starts from 1.
64: 	 * If you don't know lg_base, ndelta or lg_delta, see sc.h.
65: 	 * |xxxxxxxxxxxxxxxxxxxx|------------------------|yyyyyyyyyyyyyyyyyyyyy|
66: 	 * |<-- len: lg_base -->|<-- len: SC_LG_NGROUP-->|<-- len: lg_delta -->|
67: 	 *                      |<--      ndelta      -->|
68: 	 * rg_inner_off = ndelta - 1
69: 	 * Why use (psz - 1)?
70: 	 * To handle case: psz % (1 << lg_delta) == 0.
71: 	 */
72: 	pszind_t rg_inner_off = (((psz - 1)) >> lg_delta) & (SC_NGROUP - 1);
73: 
74: 	pszind_t base_ind = off_to_first_ps_rg << SC_LG_NGROUP;
75: 	pszind_t ind = base_ind + rg_inner_off;
76: 	return ind;
77: }
