80: sz_pind2sz_compute(pszind_t pind) {
81: 	if (unlikely(pind == SC_NPSIZES)) {
82: 		return SC_LARGE_MAXCLASS + PAGE;
83: 	}
84: 	size_t grp = pind >> SC_LG_NGROUP;
85: 	size_t mod = pind & ((ZU(1) << SC_LG_NGROUP) - 1);
86: 
87: 	size_t grp_size_mask = ~((!!grp)-1);
88: 	size_t grp_size = ((ZU(1) << (LG_PAGE + (SC_LG_NGROUP-1))) << grp)
89: 	    & grp_size_mask;
90: 
91: 	size_t shift = (grp == 0) ? 1 : grp;
92: 	size_t lg_delta = shift + (LG_PAGE-1);
93: 	size_t mod_size = (mod+1) << lg_delta;
94: 
95: 	size_t sz = grp_size + mod_size;
96: 	return sz;
97: }
