/*
 * reg_size_compute(lg_base, lg_delta, ndelta)
 * --------------------------------------------------------------------
 * 公式：size = (1<<lg_base) + ndelta*(1<<lg_delta)
 *
 * 默认代入 (x86_64, LG_PAGE=12, SC_LG_NGROUP=2)：
 *   (3, 3, 0)   → 8    B    tiny 段唯一档
 *   (3, 3, 1)   → 16   B    pseudo 组首档（特殊编码）
 *   (6, 4, 1)   → 80   B    首个常规组
 *   (13, 11, 3) → 14336 B   small 段最后一档（SC_SMALL_MAXCLASS）
 *   (13, 11, 4) → 16384 B   large 段起点（SC_LARGE_MINCLASS）
 *   (62, 60, 3) → 7.34 EiB  全表最后一档（SC_LARGE_MAXCLASS）
 *
 * 整个 size_classes 表中所有 232 档的字节数都由这个公式闭式生成。
 */
size_t
reg_size_compute(int lg_base, int lg_delta, int ndelta) {
	return (ZU(1) << lg_base) + (ZU(ndelta) << lg_delta);
}

