	sc->ndelta = ndelta;
	/* 反推本档字节数（与 reg_size_compute 同公式）。 */
	size_t size = reg_size_compute(lg_base, lg_delta, ndelta);
	/* 字段 psz：是否整页倍数。例 80→n，4096→Y，8192→Y，12288→Y。 */
